from pathlib import Path
import json,shutil,html
D=Path(__file__).parent;SITE=D.parents[1];OUT=SITE/'dist/design-preview/persona3';OUT.mkdir(parents=True,exist_ok=True)
def main():
 records=json.loads(((SITE/'content/published-projects.json') if (SITE/'content/published-projects.json').exists() else (D/'projects.json')).read_text());assert len(records)==26
 data=json.dumps(records,ensure_ascii=False).replace('</','<\\/');home=(D/'home.html').read_text();css=(D/'style.css').read_text();js=(D/'app.js').read_text()
 s='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0731ac"><meta name="description" content="Prathamesh Singh portfolio design preview. Explore economics, finance and data projects in a Persona 3 inspired interface."><title>Prathamesh Singh | Design preview</title><link rel="icon" href="/assets/mark.svg" type="image/svg+xml"><link rel="preload" href="assets/barlow-condensed-bold.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="style.css"></head><body data-view="home" data-motion="on"><a class="skip" href="#main">Skip to content</a><div class="scene" aria-hidden="true"></div><div class="rays" aria-hidden="true"></div><div class="orbital" aria-hidden="true"></div><header class="app-header"><a class="brand" href="#home" aria-label="Prathamesh Singh menu"><span class="brand-symbol" aria-hidden="true">PS</span><span class="brand-name">PRATHAMESH<br>SINGH</span></a><a class="preview-link" href="/">DESIGN PREVIEW / CURRENT SITE ↗</a></header><a class="return-menu" href="#home"><span>← BACK TO MENU</span></a><main id="main" tabindex="-1">'''+home+'''</main><div class="persistent-controls"><button id="motion" class="toggle" type="button" aria-pressed="true">Motion: on</button><button id="sound" class="toggle" type="button" aria-pressed="false">Sound: off</button></div><div id="transition-stripe" class="transition-stripe" aria-hidden="true"></div><script type="application/json" id="home-template">'''+json.dumps(home).replace('</','<\\/')+'''</script><script type="application/json" id="portfolio-data">'''+data+'''</script><script src="app.js"></script><noscript><p class="no-script">This design preview uses JavaScript for its menus. <a href="/projects/">Explore all projects on the current site</a> or <a href="/assets/prathamesh-singh-resume.pdf">open the résumé</a>.</p></noscript></body></html>'''
 (OUT/'index.html').write_text(s)
 (OUT/'style.css').write_text(css+'''\n.persistent-controls{position:fixed;z-index:40;bottom:22px;left:4.3vw;display:flex;gap:20px;color:#071a36;font-size:9px;font-weight:700;letter-spacing:.08em}body[data-view="home"] .home-footer{padding-left:330px}body:not([data-view="home"]) .persistent-controls{background:#031b50;color:#d5edff;padding:8px 14px;bottom:14px;left:18px;box-shadow:0 0 0 1px #7dc3ef33}.no-script{position:fixed;z-index:90;inset:35% 10% auto;background:#031b50;border:2px solid #15ddee;color:white;padding:40px}@media(max-width:720px){.persistent-controls{left:22px;bottom:24px;color:#effbff;font-size:8px;gap:15px}body[data-view="home"] .home-footer{padding-left:0;justify-content:flex-end}body[data-view="home"] .home-footer .keyboard-hint{display:none}body:not([data-view="home"]) .persistent-controls{bottom:10px;left:10px;font-size:9px}}\n''')
 shutil.copy2(D/'app.js',OUT/'app.js');shutil.copytree(D/'assets',OUT/'assets',dirs_exist_ok=True)
 print(json.dumps(dict(preview=str(OUT),projects=len(records),source_style='Original implementation inspired by wal-z1/persona3-portfolio; no source code or media copied',original_site='Unchanged')))
